def frozen_schema_sql(name: str) -> str:
    try:
        return {
            "0001": FROZEN_0001_SQL,
            "0002": FROZEN_0002_SQL,
            "unversioned": FROZEN_UNVERSIONED_0002_SQL,
        }[name]
    except KeyError as exc:
        raise ValueError(f"unknown frozen baseline: {name}") from exc


def apply_frozen_schema(bind: Any, name: str) -> None:
    """Apply immutable SQLite DDL without consulting application metadata."""
    connection = getattr(bind, "connection", bind)
    raw = getattr(connection, "driver_connection", connection)
    raw.executescript(frozen_schema_sql(name))


def _canonical_sql(sql: str | None) -> str | None:
    return None if sql is None else " ".join(sql.split())


def schema_manifest(connection: sqlite3.Connection, *, include_alembic: bool = False) -> dict[str, Any]:
    rows = connection.execute(
        "SELECT name, sql FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name"
    ).fetchall()
    tables: list[dict[str, Any]] = []
    for name, sql in rows:
        if not include_alembic and name == "alembic_version":
            continue
        columns = [
            {
                "name": row[1],
                "type": row[2],
                "notnull": row[3],
                "default": row[4],
                "primary_key": row[5],
            }
            for row in connection.execute(f"PRAGMA table_info({_quote_identifier(name)})")
        ]
        foreign_keys = [
            {
                "id": row[0],
                "sequence": row[1],
                "table": row[2],
                "from": row[3],
                "to": row[4],
                "on_update": row[5],
                "on_delete": row[6],
                "match": row[7],
            }
            for row in connection.execute(f"PRAGMA foreign_key_list({_quote_identifier(name)})")
        ]
        indexes = []
        for index in connection.execute(f"PRAGMA index_list({_quote_identifier(name)})"):
            index_name = index[1]
            index_sql = connection.execute(
                "SELECT sql FROM sqlite_master WHERE type='index' AND name=?", (index_name,)
            ).fetchone()
            indexes.append(
                {
                    "name": index_name,
                    "unique": index[2],
                    "origin": index[3],
                    "partial": index[4],
                    "columns": [column[2] for column in connection.execute(f"PRAGMA index_info({_quote_identifier(index_name)})")],
                    "sql": _canonical_sql(index_sql[0] if index_sql else None),
                }
            )
        indexes.sort(key=lambda index: index["name"])
        tables.append({"name": name, "sql": _canonical_sql(sql), "columns": columns, "foreign_keys": foreign_keys, "indexes": indexes})
    return {"tables": tables}


def schema_fingerprint(connection: sqlite3.Connection, *, include_alembic: bool = False) -> str:
    payload = json.dumps(schema_manifest(connection, include_alembic=include_alembic), sort_keys=True, separators=(",", ":"))
    return sha256(payload.encode("utf-8")).hexdigest()


def classify_database(path: Path | str) -> BaselineState:
    database_path = Path(path)
    if not database_path.exists():
        raise SchemaMismatch(f"database does not exist: {database_path}")
    connection = sqlite3.connect(f"file:{database_path.resolve()}?mode=ro", uri=True)
    try:
        return _classify_connection(connection)
    finally:
        connection.close()


def _classify_connection(connection: sqlite3.Connection) -> BaselineState:
    names = {
        row[0]
        for row in connection.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'")
    }
    if not names:
        return BaselineState.EMPTY
    has_alembic = "alembic_version" in names
    shape = schema_fingerprint(connection)
    if not has_alembic:
        if shape == _frozen_fingerprint("unversioned"):
            return BaselineState.UNVERSIONED_0002
        raise SchemaMismatch("database shape does not match the exact unversioned legacy baseline")
    version = _read_exact_alembic_version(connection)
    if version == ALEMBIC_0001 and shape == _frozen_fingerprint("0001"):
        return BaselineState.STAMPED_0001
    if version == ALEMBIC_0002 and shape == _frozen_fingerprint("0002"):
        return BaselineState.STAMPED_0002
    if version == ALEMBIC_PREVIOUS_HEAD and _PREVIOUS_HEAD_REQUIRED_TABLES <= names:
        return BaselineState.HEAD_MARKED if _has_committed_marker(connection) else BaselineState.HEAD_UNMARKED
    if version == ALEMBIC_INTERMEDIATE_HEAD and _HEAD_REQUIRED_TABLES <= names:
        return BaselineState.HEAD_MARKED if _has_committed_marker(connection) else BaselineState.HEAD_UNMARKED
    if version == ALEMBIC_SOURCE_HEAD and _HEAD_REQUIRED_TABLES <= names:
        return BaselineState.HEAD_MARKED if _has_committed_marker(connection) else BaselineState.HEAD_UNMARKED
    if version == ALEMBIC_ASSET_TIMESTAMP_HEAD and _HEAD_REQUIRED_TABLES <= names:
        return BaselineState.HEAD_MARKED if _has_committed_marker(connection) else BaselineState.HEAD_UNMARKED
    if version == ALEMBIC_CHECKPOINT_REVISION_HEAD and _HEAD_REQUIRED_TABLES <= names:
        return BaselineState.HEAD_MARKED if _has_committed_marker(connection) else BaselineState.HEAD_UNMARKED
    if version == ALEMBIC_INLINE_PROMPTS_HEAD and _HEAD_REQUIRED_TABLES <= names:
        return BaselineState.HEAD_MARKED if _has_committed_marker(connection) else BaselineState.HEAD_UNMARKED
    if version == ALEMBIC_GENERATION_QUEUE_HEAD and _HEAD_REQUIRED_TABLES <= names:
        return BaselineState.HEAD_MARKED if _has_committed_marker(connection) else BaselineState.HEAD_UNMARKED
    if version in ALEMBIC_POST_QUEUE_REVISIONS and _HEAD_REQUIRED_TABLES <= names:
        return BaselineState.HEAD_MARKED if _has_committed_marker(connection) else BaselineState.HEAD_UNMARKED

    if version == ALEMBIC_HEAD and _HEAD_REQUIRED_TABLES <= names:
        return BaselineState.HEAD_MARKED if _has_committed_marker(connection) else BaselineState.HEAD_UNMARKED
    raise SchemaMismatch("database version and schema shape do not match a supported baseline")


def _frozen_fingerprint(name: str) -> str:
    connection = sqlite3.connect(":memory:")
    try:
        connection.executescript(frozen_schema_sql(name))
        return schema_fingerprint(connection)
    finally:
        connection.close()


def _read_exact_alembic_version(connection: sqlite3.Connection) -> str:
    columns = connection.execute("PRAGMA table_info(alembic_version)").fetchall()
    if len(columns) != 1 or columns[0][1:3] != ("version_num", "VARCHAR(32)") or not columns[0][3]:
        raise SchemaMismatch("alembic version table shape is not supported")
    values = connection.execute("SELECT version_num FROM alembic_version").fetchall()
    if len(values) != 1 or not isinstance(values[0][0], str):
        raise SchemaMismatch("alembic version table must contain exactly one revision")
    return values[0][0]


def _has_committed_marker(connection: sqlite3.Connection) -> bool:
    try:
        row = connection.execute("SELECT marker FROM storage_cutover_marker WHERE id=1").fetchone()
    except sqlite3.OperationalError:
        return False
    return row == (1,)


def _quote_identifier(value: str) -> str:
    return '"' + value.replace('"', '""') + '"'
